SELECT u.*, d.name AS dept_name
FROM sys_user u
LEFT JOIN sys_dept d ON d.id = u.dept_id AND d.deleted = 0

    u.deleted = 0

        AND u.account LIKE CONCAT('%', #{query.account}, '%')


        AND u.nickname LIKE CONCAT('%', #{query.nickname}, '%')


        AND u.phone LIKE CONCAT('%', #{query.phone}, '%')


        AND u.status = #{query.status}


        AND u.dept_id = #{query.deptId}


        AND u.create_time >= #{query.createTimeStart}


        AND u.create_time <= #{query.createTimeEnd}


ORDER BY u.create_time DESC

